import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

import type { FormEvent } from "react";

export const fieldLabelStyles =
  "text-sm font-medium text-foreground [overflow-wrap:anywhere]";
export const fieldDescriptionStyles =
  "text-xs leading-5 text-muted-foreground [overflow-wrap:anywhere]";
export const fieldErrorStyles =
  "text-xs leading-5 text-destructive [overflow-wrap:anywhere]";

export const fieldInputStyles =
  "min-h-12 w-full cursor-text rounded-lg border border-input bg-card text-base text-foreground shadow-[var(--shadow-card)] outline-none transition-[color,background-color,border-color,box-shadow] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] placeholder:text-muted-foreground/80 hover:border-primary/45 focus:border-ring focus:ring-3 focus:ring-ring/50 invalid:border-destructive invalid:ring-3 invalid:ring-destructive/20 invalid:hover:border-destructive invalid:focus:border-destructive invalid:focus:ring-destructive/30 [&[readonly]]:bg-muted/40 [&[readonly]]:hover:border-input disabled:cursor-not-allowed disabled:bg-muted disabled:opacity-60 disabled:hover:border-input sm:text-sm";

export const segmentedFieldStyles =
  "flex min-h-12 min-w-0 items-center rounded-lg border border-input bg-card shadow-[var(--shadow-card)] transition-[color,background-color,border-color,box-shadow] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:border-primary/45 focus-within:border-ring focus-within:hover:border-ring focus-within:ring-3 focus-within:ring-ring/50 group-invalid:border-destructive group-invalid:ring-3 group-invalid:ring-destructive/20 group-invalid:hover:border-destructive group-invalid:focus-within:border-destructive group-invalid:focus-within:hover:border-destructive group-invalid:focus-within:ring-destructive/30 group-data-[readonly]:bg-muted/40 group-data-[readonly]:hover:border-input group-disabled:bg-muted group-disabled:opacity-60 group-disabled:hover:border-input";

export const fieldTriggerStyles =
  "grid size-11 shrink-0 cursor-pointer place-items-center rounded-md text-muted-foreground outline-none transition-[color,background-color] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:bg-muted hover:text-foreground pressed:bg-muted pressed:text-foreground focus-visible:-outline-offset-2 focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-ring disabled:cursor-default disabled:opacity-50";

export function revalidateOnInput(
  event: FormEvent<HTMLInputElement | HTMLTextAreaElement>,
) {
  const field = event.currentTarget;
  if (field.getAttribute("aria-invalid") === "true")
    field.dispatchEvent(new Event("change"));
}

export function revalidateField(field: HTMLElement | null) {
  requestAnimationFrame(() => {
    if (!field?.hasAttribute("data-invalid")) return;
    for (const input of field.querySelectorAll("input"))
      input.dispatchEvent(new Event("change"));
  });
}

"use client";

import {
  Group as AriaGroup,
  Input as AriaInput,
  TextArea as AriaTextArea,
  composeRenderProps,
  type GroupProps,
} from "react-aria-components";
import { cn } from "./utils";
import { revalidateOnInput } from "./field-styles";

export function InputGroup({ className, ...props }: GroupProps) {
  return (
    <AriaGroup
      {...props}
      data-slot="input-group"
      className={composeRenderProps(className, (className) =>
        cn(
          "flex min-h-12 w-full min-w-0 items-center gap-x-2 rounded-lg border border-input bg-card ps-3.5 pe-3.5 text-foreground shadow-[var(--shadow-card)] hover:border-primary/45 data-[focus-within]:border-ring data-[focus-within]:ring-3 data-[focus-within]:ring-ring/50 data-[invalid]:border-destructive data-[invalid]:ring-3 data-[invalid]:ring-destructive/20 data-[invalid]:hover:border-destructive data-[invalid]:data-[focus-within]:ring-destructive/30 data-[disabled]:bg-muted data-[disabled]:opacity-60 data-[disabled]:shadow-none data-[disabled]:hover:border-input has-[>[data-align=block-end]]:flex-wrap",
          className,
        ),
      )}
    />
  );
}

export function InputGroupInput({
  className,
  onInput,
  ...props
}: React.ComponentProps<typeof AriaInput>) {
  return (
    <AriaInput
      {...props}
      onInput={(event) => {
        revalidateOnInput(event);
        onInput?.(event);
      }}
      data-slot="input-group-input"
      className={composeRenderProps(className, (className) =>
        cn(
          "min-h-11 min-w-[min(8rem,50%)] flex-1 cursor-text bg-transparent py-2.5 text-base leading-6 text-foreground outline-none [&::placeholder]:text-muted-foreground/80 disabled:cursor-not-allowed sm:text-sm [&::-webkit-search-cancel-button]:hidden",
          className,
        ),
      )}
    />
  );
}

export function InputGroupTextArea({
  className,
  onInput,
  ...props
}: React.ComponentProps<typeof AriaTextArea>) {
  return (
    <AriaTextArea
      {...props}
      onInput={(event) => {
        revalidateOnInput(event);
        onInput?.(event);
      }}
      data-slot="input-group-text-area"
      className={composeRenderProps(className, (className) =>
        cn(
          "min-h-28 min-w-0 basis-full resize-y bg-transparent py-3 text-base leading-6 text-foreground outline-none [&::placeholder]:text-muted-foreground/80 disabled:cursor-not-allowed sm:text-sm",
          className,
        ),
      )}
    />
  );
}

export function InputGroupAddon({
  align = "inline",
  className,
  children,
  ...props
}: React.ComponentPropsWithRef<"span"> & { align?: "inline" | "block-end" }) {
  return (
    <span
      {...props}
      data-slot="input-group-addon"
      data-align={align}
      className={cn(
        "inline-flex min-w-0 items-center gap-2 text-sm text-muted-foreground [&_svg]:shrink-0",
        align === "block-end" &&
          "w-full justify-end border-t border-border/70 py-2",
        className,
      )}
    >
      {typeof children === "string" ? (
        <span className="min-w-0 truncate">{children}</span>
      ) : (
        children
      )}
    </span>
  );
}
